var t=`1389-colombo-de-poulet`;var n=`world-1389`;var o=`GF`;var a=`south-america`;var r=4;var s=110;var l={en:`Colombo de Poulet`,ua:`Курка коломбо`};var g={en:`Colombo de Poulet is a dish from French Guiana featuring chicken thigh, garlic, lime juice, yellow onion. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Курка коломбо, страва кухні країни Французька Гвіана з такими основними складниками: куряче стегно, часник, сік лайма, жовта цибуля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var m=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 50 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 50 хвилин.`,t:[`marinating`],m:50,i:[[`chicken-thigh`,850,`g`],[`curry-powder`,22,`g`],[`garlic`,5,`clove`],[`lime-juice`,70,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,170,`g`],[`eggplant`,260,`g`],[`canola-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 45 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 45 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:45,i:[[`coconut-milk`,460,`ml`],[`chicken-stock`,430,`ml`],[`tomato`,300,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`cilantro`,27,`g`]]}];var c={slug:t,id:n,country:`GF`,region:a,servings:4,minutes:110,title:l,text:g,steps:m};export{o as country,c as default,n as id,s as minutes,a as region,r as servings,t as slug,m as steps,g as text,l as title};